        if block_i > cache_block_id or blocktype == 'mid':
            return True
        if block_i < cache_block_id: return False
        return layer_i >= cache_layer_id if blocktype == 'down' else layer_i > cache_layer_id            def is_enter_position(self, block_i, layer_i):        return block_i == self.params['cache_block_id'] and layer_i == self.params['cache_layer_id']    def wrap_unet_forward(self):        self.function_dict['unet_forward'] = self.pipe.unet.forward        def wrapped_forward(*args, **kwargs):
            self.cur_timestep = list(self.pipe.scheduler.timesteps).index(args[1].item())
            result = self.function_dict['unet_forward'](*args, **kwargs)
            return result
        self.pipe.unet.forward = wrapped_forward    def wrap_block_forward(self, block, block_name, block_i, layer_i, blocktype = "down"):        self.function_dict[
            (blocktype, block_name, block_i, layer_i)
        ] = block.forward        def wrapped_forward(*args, **kwargs):
